using System.Diagnostics;
using System.Text.Json;
using System.Security.AccessControl;
using LocalAI.Core;

var output=Path.GetFullPath(args[0]);Directory.CreateDirectory(Path.GetDirectoryName(output)!);var root=Path.Combine(Path.GetDirectoryName(output)!,"command-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var runner=new CommandRunner([root],Path.Combine(root,"logs"));var results=new Dictionary<string,object>();
void Assert(bool value){if(!value)throw new IOException("Assertion failed.");}
async Task Reject(Func<Task> action){try{await action();}catch(Exception e)when(e is IOException or OperationCanceledException or InvalidOperationException){return;}throw new IOException("Expected refusal.");}
async Task Test(string name,Func<Task> action){try{await action();results[name]=true;}catch(Exception e){results[name]=false;Console.Error.WriteLine(name+": "+e);}}
CommandPlan Plan(string script,int seconds=10)=>runner.Preview(new(script,root,seconds));
await Test("command preview has no side effects",()=>{var plan=Plan("Set-Content 'NotExecuted.txt' 'bad'");Assert(plan.Review.Contains("EXACT COMMAND")&&!File.Exists(Path.Combine(root,"NotExecuted.txt")));return Task.CompletedTask;});
await Test("command requires explicit confirmation",()=>Reject(async()=>{await runner.Run(Plan("Set-Content 'NotExecuted.txt' 'bad'"),false);}));
await Test("command runs with real working directory and Unicode",async()=>{var run=await runner.Run(Plan("[Console]::WriteLine((Get-Location).Path);[Console]::WriteLine('héllo 世界')"),true);Assert(run.Status=="Succeeded"&&run.ExitCode==0&&run.Output.Contains(root)&&run.Output.Contains("héllo 世界"));});
await Test("command returns explicit native exit code",async()=>{var run=await runner.Run(Plan("cmd /d /c exit 7"),true);Assert(run.Status=="Failed"&&run.ExitCode==7);});
await Test("command captures terminating errors",async()=>{var run=await runner.Run(Plan("throw 'synthetic failure'"),true);Assert(run.Status=="Failed"&&run.Output.Contains("synthetic failure"));});
await Test("command can create requested project file",async()=>{var run=await runner.Run(Plan("Set-Content -LiteralPath 'Acme.html' -Value '<!doctype html><title>Acme</title><h1>Acme</h1>' -Encoding UTF8"),true);Assert(run.Status=="Succeeded"&&File.ReadAllText(Path.Combine(root,"Acme.html")).Contains("<h1>Acme</h1>"));});
await Test("command logs exact request and result",async()=>{var run=await runner.Run(Plan("Write-Output 'logged'"),true);var saved=JsonSerializer.Deserialize<CommandRun>(File.ReadAllText(run.LogPath))!;Assert(run.LogError==null&&saved.Request.Script=="Write-Output 'logged'"&&saved.Status=="Succeeded"&&saved.Output.Contains("logged"));});
await Test("command log directory has private noninherited permissions",async()=>{var run=await runner.Run(Plan("Write-Output 'private log'"),true);Assert(new DirectoryInfo(Path.GetDirectoryName(run.LogPath)!).GetAccessControl().AreAccessRulesProtected);});
await Test("command payload is absent from Windows command line",async()=>{var run=await runner.Run(Plan("[Console]::WriteLine((Get-CimInstance Win32_Process -Filter ('ProcessId='+$PID)).CommandLine); # UNIQUE_PRIVATE_PAYLOAD"),true);Assert(run.Status=="Succeeded"&&run.Output.Contains("-EncodedCommand")&&!run.Output.Contains("UNIQUE_PRIVATE_PAYLOAD"));});
await Test("command streams before completion",async()=>{var seen=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var progress=new InlineProgress(text=>{if(text.Contains("early"))seen.TrySetResult();});var task=runner.Run(Plan("[Console]::WriteLine('early');Start-Sleep -Seconds 2;[Console]::WriteLine('late')"),true,progress);await seen.Task.WaitAsync(TimeSpan.FromSeconds(5));Assert(!task.IsCompleted);Assert((await task).Output.Contains("late"));});
await Test("command timeout stops execution",async()=>{var watch=Stopwatch.StartNew();var run=await runner.Run(Plan("Start-Sleep -Seconds 30",1),true);Assert(run.Status=="TimedOut"&&watch.Elapsed<TimeSpan.FromSeconds(8));});
await Test("command cancellation stops execution",async()=>{using var stop=new CancellationTokenSource(1000);var run=await runner.Run(Plan("Start-Sleep -Seconds 30"),true,cancellation:stop.Token);Assert(run.Status=="Cancelled");});
await Test("command output cap stops noisy process",async()=>{var run=await runner.Run(Plan("while($true){[Console]::WriteLine(('x'*4096))}"),true);Assert(run.Status=="OutputLimit"&&run.Output.Length<=CommandRunner.MaximumOutputCharacters);});
await Test("command stops background children on completion",async()=>{var run=await runner.Run(Plan("$p=Start-Process -FilePath (Join-Path $PSHOME 'powershell.exe') -ArgumentList '-NoProfile','-NonInteractive','-Command','Start-Sleep -Seconds 60' -WindowStyle Hidden -PassThru;[Console]::WriteLine(('CHILD='+$p.Id))"),true);var line=run.Output.Split('\n').Single(x=>x.StartsWith("CHILD="));var pid=int.Parse(line[6..].Trim());await Task.Delay(150);try{Assert(Process.GetProcessById(pid).HasExited);}catch(ArgumentException){}Assert(run.Status=="Succeeded");});
await Test("command refuses starting folder outside connected roots",()=>Reject(()=>{runner.Preview(new("Write-Output 7",Path.GetDirectoryName(root)!));return Task.CompletedTask;}));
await Test("command refuses invalid limits",async()=>{await Reject(()=>{Plan("x",0);return Task.CompletedTask;});await Reject(()=>{Plan(new string('x',16001));return Task.CompletedTask;});});
await Test("command pre-cancellation runs nothing",async()=>{using var stop=new CancellationTokenSource();stop.Cancel();await Reject(async()=>{await runner.Run(Plan("Set-Content 'Never.txt' 'bad'"),true,cancellation:stop.Token);});Assert(!File.Exists(Path.Combine(root,"Never.txt")));});
await Test("command protocol rejects hidden and duplicate fields",()=>{foreach(var text in new[]{"{\"script\":\"x\",\"workingDirectory\":\"x\",\"autoRun\":true}","{\"script\":\"x\",\"script\":\"y\",\"workingDirectory\":\"x\"}"}){try{CommandRunner.Parse(text);throw new Exception("Protocol accepted");}catch(IOException){}}return Task.CompletedTask;});
await Test("command JSON fence recognition stays schema restricted",()=>{Assert(CommandRunner.IsProposal("json","{\"script\":\"Write-Output 7\",\"workingDirectory\":\"C:\\\\Example\"}")&&!CommandRunner.IsProposal("json","{\"example\":7}"));return Task.CompletedTask;});
await Test("command temporary work is isolated and removed",async()=>{var run=await runner.Run(Plan("[Console]::WriteLine(('TEMP='+$env:TEMP));[IO.File]::WriteAllText([IO.Path]::Combine($env:TEMP,'scratch.txt'),'temporary')"),true);var line=run.Output.Split('\n').Single(s=>s.StartsWith("TEMP="));var temporary=line[5..].Trim();Assert(run.Status=="Succeeded"&&run.LogError==null&&Path.GetFileName(temporary).StartsWith("Infinity-command-")&&!Directory.Exists(temporary));});
await Test("command temporary cleanup never follows junction targets",async()=>{var target=Path.Combine(root,"KeepTarget");Directory.CreateDirectory(target);var sentinel=Path.Combine(target,"Keep.txt");File.WriteAllText(sentinel,"keep");var quoted=target.Replace("'","''");var run=await runner.Run(Plan("New-Item -ItemType Junction -Path ([IO.Path]::Combine($env:TEMP,'linked')) -Target '"+quoted+"' | Out-Null"),true);Assert(run.Status=="Succeeded"&&run.LogError==null&&File.ReadAllText(sentinel)=="keep");});
File.WriteAllText(output,JsonSerializer.Serialize(results,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(JsonSerializer.Serialize(new{passed=results.Values.All(v=>v is true),count=results.Count,root}));Environment.ExitCode=results.Values.All(v=>v is true)?0:1;
sealed class InlineProgress(Action<string> action):IProgress<string>{public void Report(string value)=>action(value);}
